files.badge.py:
def render(status):
    return f'<span class="badge">{status}</span>'


def preview():
    return "<div>" + "".join(render(s) for s in ("pass", "fail", "running")) + "</div>"

files.progress.py:
def render(done, total):
    pct = int(100 * done / total)
    return (f'<div class="progress"><div class="bar" style="width: {pct}%"></div>'
            f'<span>{pct}%</span></div>')


def preview():
    return "<div>" + render(1, 3) + render(3, 3) + "</div>"
